import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.CWgsre3x.js";const u=JSON.parse('{"title":"Ασφάλεια, ιδιωτικότητα και ΓΚΠΔ","description":"","frontmatter":{},"headers":[],"relativePath":"el/security-privacy/index.md","filePath":"el/security-privacy/index.md"}'),i={name:"el/security-privacy/index.md"};function o(n,a,d,h,s,p){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="ασφαλεια-ιδιωτικοτητα-και-γκπδ" tabindex="-1">Ασφάλεια, ιδιωτικότητα και ΓΚΠΔ <a class="header-anchor" href="#ασφαλεια-ιδιωτικοτητα-και-γκπδ" aria-label="Permalink to &quot;Ασφάλεια, ιδιωτικότητα και ΓΚΠΔ&quot;">​</a></h1><p>Ο οδηγός αφορά την ασφαλή χρήση του TransferBook+ και την προετοιμασία επιχειρήσεων μεταφορών για την προστασία προσωπικών δεδομένων.</p><div class="warning custom-block"><p class="custom-block-title">Πεδίο εφαρμογής</p><p>Δεν αποτελεί δήλωση απορρήτου, σύμβαση επεξεργασίας δεδομένων, πιστοποίηση ασφάλειας ή εγγύηση συμμόρφωσης με τον ΓΚΠΔ. Η υφιστάμενη τεκμηρίωση API και ρόλων αναφέρεται στην έκδοση αναφοράς v0.7.9. Κάθε λειτουργία και μέτρο πρέπει να επαληθεύεται στην εγκεκριμένη έκδοση και εγκατάσταση. Οι συστάσεις δεν δηλώνουν ότι όλα τα μέτρα έχουν ήδη υλοποιηθεί.</p></div><h2 id="λογαριασμοι-και-διαχωρισμος-εταιρειων" tabindex="-1">Λογαριασμοί και διαχωρισμός εταιρειών <a class="header-anchor" href="#λογαριασμοι-και-διαχωρισμος-εταιρειων" aria-label="Permalink to &quot;Λογαριασμοί και διαχωρισμός εταιρειών&quot;">​</a></h2><p>Η τεκμηρίωση αναφοράς περιγράφει επαλήθευση διακριτικών RS256, ανεξάρτητους ελέγχους συμμετοχής στην εταιρεία και δικαιωμάτων, καθώς και ρόλους διαχειριστή, υπεύθυνου αναθέσεων, οδηγού και παρατηρητή. Η επιλογή εταιρείας δεν παρέχει από μόνη της εξουσιοδότηση. Η πρόσβαση οδηγών περιορίζεται στις εγκεκριμένες εργασίες.</p><ul><li>Χρησιμοποιήστε ατομικούς λογαριασμούς, ελάχιστα αναγκαία δικαιώματα και ισχυρούς μοναδικούς κωδικούς.</li><li>Ανακαλέστε έγκαιρα την πρόσβαση όταν αλλάζουν οι αρμοδιότητες ή αποχωρεί εργαζόμενος.</li><li>Ελέγξτε τη λήξη συνεδρίας, την αποσύνδεση, την ανάκτηση λογαριασμού και την απομόνωση εταιρειών στο API.</li><li>Μην κοινοποιείτε διακριτικά πρόσβασης, κωδικούς ή στοιχεία επιβατών σε δημόσιες σελίδες και μη ασφαλή αιτήματα υποστήριξης.</li></ul><p>Δείτε <a href="/el/developers/authentication.html">ταυτοποίηση και πρόσβαση εταιρείας</a> και <a href="/el/developers/permissions.html">ρόλους και δικαιώματα</a>.</p><h2 id="στοιχεια-επιβατων-οδηγων-και-πληρωμων" tabindex="-1">Στοιχεία επιβατών, οδηγών και πληρωμών <a class="header-anchor" href="#στοιχεια-επιβατων-οδηγων-και-πληρωμων" aria-label="Permalink to &quot;Στοιχεία επιβατών, οδηγών και πληρωμών&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Δεδομένα</th><th>Ορθή διαχείριση</th></tr></thead><tbody><tr><td>Όνομα, τηλέφωνο και προαιρετικό email</td><td>Συλλογή μόνο για αναγκαίο και δικαιολογημένο σκοπό· ποτέ επινοημένη διεύθυνση email</td></tr><tr><td>Σημεία παραλαβής, προορισμοί και δρομολόγια</td><td>Κοινοποίηση μόνο σε όσους τα χρειάζονται για την υπηρεσία</td></tr><tr><td>Στοιχεία οδηγών, αναθέσεις και τοποθεσία</td><td>Περιορισμένη πρόσβαση, ενημέρωση για τους σκοπούς και αξιολόγηση αναγκαιότητας και αναλογικότητας</td></tr><tr><td>Σημειώσεις VIP και ιστορικό</td><td>Αποφυγή περιττών ευαίσθητων πληροφοριών και αδικαιολόγητης κατάρτισης προφίλ</td></tr><tr><td>Πληρωμές και αναφορές συναλλαγών</td><td>Εγκεκριμένες διαδικασίες· ποτέ αριθμοί καρτών ή κωδικοί ασφαλείας σε σημειώσεις</td></tr></tbody></table><p>Δείτε <a href="/el/plus/passenger-information.html">στοιχεία επιβατών</a>, <a href="/el/plus/payments-and-reconciliation.html">πληρωμές και συμφωνία συναλλαγών</a> και <a href="/el/integrations/payment-providers.html">ετοιμότητα παρόχων πληρωμών</a>. Η εμφάνιση ενός παρόχου δεν αποδεικνύει ενεργή διασύνδεση ή πιστοποίηση PCI DSS.</p><p>Τα κανάλια μηνυμάτων και τεχνητής νοημοσύνης χρειάζονται χωριστή έγκριση και έλεγχο της ροής δεδομένων. Η συναλλακτική συγκατάθεση ή η ένδειξη συγκατάθεσης σε δοκιμαστικό περιβάλλον δεν αποτελεί άδεια εμπορικής προώθησης ούτε τεκμηρίωση νόμιμης βάσης επεξεργασίας. Για εκπαίδευση και δοκιμές χρησιμοποιήστε συνθετικά δεδομένα. Δείτε <a href="/el/integrations/conversational-booking.html">κρατήσεις μέσω συνομιλίας</a>.</p><h2 id="υποχρεωσεις-βασει-γκπδ" tabindex="-1">Υποχρεώσεις βάσει ΓΚΠΔ <a class="header-anchor" href="#υποχρεωσεις-βασει-γκπδ" aria-label="Permalink to &quot;Υποχρεώσεις βάσει ΓΚΠΔ&quot;">​</a></h2><p>Όπου εφαρμόζεται ο ΓΚΠΔ, προσδιορίστε τον υπεύθυνο επεξεργασίας, τυχόν από κοινού υπευθύνους και τους εκτελούντες την επεξεργασία ανά σκοπό. Η επιχείρηση που αποφασίζει τους σκοπούς και τα μέσα επεξεργασίας στοιχείων επιβατών είναι κατά κανόνα υπεύθυνος επεξεργασίας για τη συγκεκριμένη δραστηριότητα. Ο πάροχος που επεξεργάζεται δεδομένα για λογαριασμό της μπορεί να είναι εκτελών την επεξεργασία. Οι πραγματικοί ρόλοι εξαρτώνται από τις δραστηριότητες και τις συμφωνίες.</p><ul><li>Τεκμηριώστε τους σκοπούς, τις κατηγορίες δεδομένων, τους αποδέκτες και τη νόμιμη βάση. Εξετάστε χωριστά τυχόν αναγκαία δεδομένα ειδικών κατηγοριών.</li><li>Παρέχετε κατάλληλη ενημέρωση απορρήτου και διαδικασία άσκησης δικαιωμάτων.</li><li>Συμφωνήστε τους όρους του άρθρου 28, όπου απαιτείται, συμπεριλαμβανομένων των υπεργολάβων επεξεργασίας. Ελέγξτε τις διεθνείς διαβιβάσεις βάσει του κεφαλαίου V.</li><li>Τηρείτε τα απαιτούμενα αρχεία επεξεργασίας. Εξετάστε την ανάγκη υπευθύνου προστασίας δεδομένων και εκτίμησης αντικτύπου, ιδίως για επεξεργασία υψηλού κινδύνου όπως συστηματική παρακολούθηση τοποθεσίας.</li><li>Ελέγξτε χωριστά τους κανόνες εμπορικής επικοινωνίας και ηλεκτρονικών επικοινωνιών.</li></ul><h2 id="διατηρηση-δεδομενων-και-δικαιωματα" tabindex="-1">Διατήρηση δεδομένων και δικαιώματα <a class="header-anchor" href="#διατηρηση-δεδομενων-και-δικαιωματα" aria-label="Permalink to &quot;Διατήρηση δεδομένων και δικαιώματα&quot;">​</a></h2><p>Ορίστε περιόδους διατήρησης ανά σκοπό και νόμιμη υποχρέωση, συμπεριλαμβανομένων των οικονομικών αρχείων, καταγραφών, αντιγράφων ασφαλείας και αιτημάτων υποστήριξης. Διαγράψτε ή ανωνυμοποιήστε κατάλληλα δεδομένα όταν δεν δικαιολογείται πλέον η διατήρησή τους, με την επιφύλαξη νόμιμων υποχρεώσεων.</p><p>Οργανώστε ασφαλή διαδικασία για πρόσβαση, διόρθωση, διαγραφή, περιορισμό, φορητότητα, εναντίωση και λοιπά εφαρμοστέα δικαιώματα. Ισχύουν οι αντίστοιχες προϋποθέσεις και εξαιρέσεις. Κατά το άρθρο 12, η απάντηση παρέχεται κατά κανόνα εντός ενός μήνα. Όπου δικαιολογείται, η προθεσμία μπορεί να παραταθεί έως δύο ακόμη μήνες, με ενημέρωση μέσα στον πρώτο μήνα. Ελέγξτε αναλογικά την ταυτότητα και προστατεύστε τα δεδομένα τρίτων.</p><p>Επαληθεύστε τις διαθέσιμες λειτουργίες εξαγωγής, διόρθωσης και διαγραφής. Όπου δεν έχει επιβεβαιωθεί αυτοματοποίηση, εφαρμόστε εγκεκριμένη διοικητική διαδικασία.</p><h2 id="καταγραφες-φιλοξενια-και-περιστατικα" tabindex="-1">Καταγραφές, φιλοξενία και περιστατικά <a class="header-anchor" href="#καταγραφες-φιλοξενια-και-περιστατικα" aria-label="Permalink to &quot;Καταγραφές, φιλοξενία και περιστατικά&quot;">​</a></h2><p>Ο έλεγχος αποδοχής πρέπει να καλύπτει HTTPS, ενημερώσεις ασφαλείας, προστασία μυστικών και βάσεων δεδομένων, κατάλληλη κρυπτογράφηση, αντίγραφα ασφαλείας, δοκιμές επαναφοράς, περιορισμό πρόσβασης στις καταγραφές, παρακολούθηση και αντιμετώπιση ευπαθειών. Καθορίστε υπεύθυνο επικοινωνίας, διαδικασία περιορισμού περιστατικών και διατήρηση αποδεικτικών στοιχείων.</p><p>Σε πιθανή παραβίαση, ενημερώστε άμεσα μέσω του συμφωνημένου ασφαλούς καναλιού. Ο εκτελών την επεξεργασία ενημερώνει τον υπεύθυνο χωρίς αδικαιολόγητη καθυστέρηση αφού λάβει γνώση παραβίασης προσωπικών δεδομένων. Όπου απαιτείται γνωστοποίηση, ο υπεύθυνος ενημερώνει την αρμόδια εποπτική αρχή χωρίς αδικαιολόγητη καθυστέρηση και, εφόσον είναι εφικτό, εντός 72 ωρών από τη στιγμή που έλαβε γνώση. Παραβιάσεις υψηλού κινδύνου απαιτούν κατά κανόνα και ενημέρωση των επηρεαζόμενων προσώπων χωρίς αδικαιολόγητη καθυστέρηση, με τις εξαιρέσεις του άρθρου 34.</p><p>Δείτε <a href="/el/installation/">Εγκατάσταση και ανάπτυξη</a> για προετοιμασία και ανάκτηση.</p><h2 id="πριν-απο-την-εμπορικη-ενεργοποιηση" tabindex="-1">Πριν από την εμπορική ενεργοποίηση <a class="header-anchor" href="#πριν-απο-την-εμπορικη-ενεργοποιηση" aria-label="Permalink to &quot;Πριν από την εμπορική ενεργοποίηση&quot;">​</a></h2><p>Καταγράψτε την ελεγμένη έκδοση, τα εγκεκριμένα μέτρα, τους υπευθύνους, τους εκκρεμείς κινδύνους και τους συμφωνημένους όρους προστασίας δεδομένων. Επαληθεύστε την απομόνωση εταιρειών, την κάλυψη καταγραφών, τις διαδικασίες διατήρησης και άσκησης δικαιωμάτων, τις συμβάσεις παρόχων και τις δοκιμές επαναφοράς. Μην προβάλλετε μη ελεγμένα μέτρα ως πιστοποιημένα ή ως εγγύηση συμμόρφωσης.</p><h2 id="επισημες-πηγες" tabindex="-1">Επίσημες πηγές <a class="header-anchor" href="#επισημες-πηγες" aria-label="Permalink to &quot;Επίσημες πηγές&quot;">​</a></h2><ul><li><a href="https://eur-lex.europa.eu/legal-content/EL/TXT/?uri=CELEX%3A32016R0679" target="_blank" rel="noreferrer">Κανονισμός (ΕΕ) 2016/679 (ΓΚΠΔ)</a></li><li><a href="https://www.edpb.europa.eu/sme/be-compliant/be-compliant_en" target="_blank" rel="noreferrer">Ευρωπαϊκό Συμβούλιο Προστασίας Δεδομένων — οδηγός για μικρές επιχειρήσεις</a></li><li><a href="https://www.edpb.europa.eu/sme/assess-the-risks/data-breaches_en" target="_blank" rel="noreferrer">EDPB — Παραβιάσεις δεδομένων</a></li></ul><p><a href="/security-privacy/">English</a></p>',27)])])}const m=e(i,[["render",o]]);export{u as __pageData,m as default};
